int pos = -1;                      // -1 means 'not found yet'
for (int i = 0; i < n; i++) {
    if (a[i] == key) {             // == compares, = would assign
        pos = i;                   // remember the index
        break;                     // stop at the first match
    }
}
if (pos != -1) {
    cout << "Found at index " << pos;
} else {
    cout << "Not found";
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    int a[8] = {23, 7, 45, 12, 9, 56, 31, 18};
    int key;
    int pos = -1;
    cin >> key;
    for (int i = 0; i < 8; i++) {
        if (a[i] == key) {
            pos = i;
            break;
        }
    }
    if (pos != -1) {
        cout << key << " found at index " << pos << endl;
    } else {
        cout << key << " not found" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[6] = {4, 9, 4, 7, 4, 2};
    int key;
    cin >> key;
    int count = 0;
    cout << "Positions:";
    for (int i = 0; i < 6; i++) {
        if (a[i] == key) {
            cout << " " << i;
            count++;
        }
    }
    cout << endl;
    cout << key << " appears " << count << " time(s)" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int MAX = 20;
    int a[MAX];
    int n, key;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    cin >> key;
    bool found = false;
    int comparisons = 0;
    int position = -1;
    for (int i = 0; i < n; i++) {
        comparisons++;
        if (a[i] == key) {
            found = true;
            position = i + 1;
            break;
        }
    }
    if (found) {
        cout << "Found at position " << position << " after " << comparisons << " comparisons" << endl;
    } else {
        cout << "Not found after " << comparisons << " comparisons" << endl;
    }
    return 0;
}

